; Jump table and symbol table, generated by tools/gen.py.

SYM_ADDR    equ 0
SYM_SIZE    equ 8
SYM_SLOT    equ 16
SYM_SRC     equ 20
SYM_NAME    equ 32
SYM_RECORD  equ 64

%include "build/gen/jt.inc"
%include "build/gen/symtab.inc"

; name: sym_dump
; in:   none
; out:  "[sym] name address size slot src" per function on the log
; clobbers: caller-saved
sym_dump:
    push rbx
    push r12
    sub rsp, 8
    lea rbx, [rel sym_table]
    xor r12d, r12d
.record:
    lea rdi, [rel sym_msg_sym]
    call kputs
    lea rdi, [rbx + SYM_NAME]
    call kputs
    mov edi, ' '
    call kputc
    mov rdi, [rbx + SYM_ADDR]
    call kput_hex
    mov edi, ' '
    call kputc
    mov rdi, [rbx + SYM_SIZE]
    call [rel jt_kput_dec]
    mov edi, ' '
    call kputc
    movsxd rdi, dword [rbx + SYM_SLOT]
    call sym_put_signed
    mov edi, ' '
    call kputc
    movsxd rdi, dword [rbx + SYM_SRC]
    call sym_put_signed
    mov edi, 10
    call kputc
    add rbx, SYM_RECORD
    inc r12d
    cmp r12d, SYM_COUNT
    jb .record
    add rsp, 8
    pop r12
    pop rbx
    ret

; name: sym_put_signed
; in:   rdi = signed value
; out:  decimal on the log, with '-' when negative
; clobbers: caller-saved
sym_put_signed:
    test rdi, rdi
    jns .positive
    push rdi
    mov edi, '-'
    call kputc
    pop rdi
    neg rdi
.positive:
    jmp [rel jt_kput_dec]

sym_msg_sym     db "[sym] ", 0
